// NODE 1B — Prepare email fields for downstream nodes
const item = $input.first();
const email_from = item.json.from?.value?.[0]?.address || item.json.from || '';
const email_subject = item.json.subject || '';
const email_body = (item.json.text || item.json.html || '').slice(0, 1500);
const attachments = item.json.attachments || [];
const received_at = item.json.date || new Date().toISOString();

return [{
  json: {
    email_from,
    email_subject,
    email_body,
    attachments,
    received_at
  },
  binary: item.binary
}];

// Parse AI JSON response and merge with email context
const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { is_job_application: false, applied_role: 'unknown', confidence: 0 };
}

const email_ctx = $('Prepare Email Fields').first().json;

return [{
  json: {
    ...email_ctx,
    is_job_application: parsed.is_job_application === true,
    applied_role: parsed.applied_role || 'unknown',
    confidence: parseFloat(parsed.confidence) || 0
  },
  binary: $('Prepare Email Fields').first().binary
}];

// NODE 4/5 — Attachment Type Filter + Existence Check
const ALLOWED_MIME_TYPES = [
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
];

const allData = $input.first();
const rawAttachments = allData.json.attachments || [];

// Filter to only valid resume MIME types
const validAttachments = rawAttachments.filter(a =>
  ALLOWED_MIME_TYPES.includes((a.contentType || a.mimeType || '').toLowerCase())
);

const hasValidAttachment = validAttachments.length > 0;

return [{
  json: {
    ...allData.json,
    attachments: validAttachments,
    has_valid_attachment: hasValidAttachment,
    first_attachment_name: validAttachments[0]?.filename || null,
    first_attachment_key: validAttachments[0]?.id || Object.keys(allData.binary || {})[0] || null
  },
  binary: allData.binary
}];

// NODE 6b — Validate extracted text length
const emailCtx = $('Attachment Type Filter').first().json;
const extracted = $input.first().json;
const text = (extracted.text || extracted.data || '').toString().trim();
const text_valid = text.length >= 100;

return [{
  json: {
    ...emailCtx,
    resume_raw_text: text,
    text_valid
  }
}];

// NODE 8 — Validate Required Fields from parsed resume
const emailCtx = $('Validate Text Length').first().json;
const aiRaw = $input.first().json.choices?.[0]?.message?.content || '{}';

let parsed;
try {
  parsed = JSON.parse(aiRaw);
} catch (e) {
  parsed = {};
}

// Node 2 classifier role TAKES PRIORITY over resume-parsed role
const canonical_role = emailCtx.applied_role || parsed.applied_role || 'unknown';

const required = ['name', 'email', 'applied_role'];
const missing = required.filter(f => !parsed[f] || parsed[f] === null);
const parse_valid = missing.length === 0;

return [{
  json: {
    ...emailCtx,
    name: parsed.name || null,
    email: parsed.email || emailCtx.email_from,
    phone: parsed.phone || null,
    applied_role: canonical_role,
    total_experience_years: parsed.total_experience_years || null,
    current_or_last_company: parsed.current_or_last_company || null,
    highest_education: parsed.highest_education || null,
    key_skills: parsed.key_skills || [],
    resume_summary: parsed.resume_summary || null,
    parse_valid,
    missing_fields: missing
  }
}];

// NODE 8b — Duplicate Check: email + role already in Applications Sheet
const candidate = $('Validate Parsed Fields').first().json;
const allRows = $input.all();

const candidateEmail = (candidate.email || '').toLowerCase().trim();
const candidateRole = (candidate.applied_role || '').toLowerCase().trim();

const duplicate = allRows.find(r => {
  const rowEmail = (r.json.email || '').toLowerCase().trim();
  const rowRole = (r.json.applied_role || '').toLowerCase().trim();
  return rowEmail === candidateEmail && rowRole === candidateRole;
});

const is_duplicate = !!duplicate;
const original_applied_at = duplicate?.json?.applied_at || null;

return [{
  json: {
    ...candidate,
    is_duplicate,
    original_applied_at
  }
}];

// NODE 9 — Role Config Check (case-insensitive, EC4 fix applied)
// To add/remove roles or change slot counts, update OPENINGS below.
const OPENINGS = {
  'software engineer': 2,
  'hr executive': 1,
  'marketing lead': 1,
  'data analyst': 0   // 0 = closed
};

const raw_role = $json.applied_role || 'unknown';
const role = raw_role.toLowerCase().trim();

const slots = OPENINGS[role];
const role_exists = slots !== undefined;
const role_open = role_exists && slots > 0;

return [{
  json: {
    ...$json,
    applied_role_normalized: role,
    role_slots: slots ?? 0,
    role_exists,
    role_open
  }
}];

// NODE 12 — Count selected applicants for this role and determine if slot is available
const candidate = $('Role Config Check').first().json;
const allRows = $input.all();

const role = candidate.applied_role_normalized;
const slots = candidate.role_slots;

const selectedCount = allRows.filter(r =>
  (r.json.applied_role || '').toLowerCase().trim() === role &&
  r.json.status === 'selected'
).length;

const canSelect = selectedCount < slots;

return [{
  json: {
    ...candidate,
    selectedCount,
    slots,
    canSelect
  }
}];
